=== FILE: axil_timer.v ===
// axil_timer: 32-bit down-counting timer with one-shot and periodic modes and
// a level interrupt, behind an AXI4-Lite subordinate port.
// Implements interface_spec.md per microarchitecture.md.
`default_nettype none

module axil_timer #(
    parameter ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,
    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,
    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,
    output wire [1:0]            s_axil_bresp,
    output wire                  s_axil_bvalid,
    input  wire                  s_axil_bready,
    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,
    output wire [31:0]           s_axil_rdata,
    output wire [1:0]            s_axil_rresp,
    output wire                  s_axil_rvalid,
    input  wire                  s_axil_rready,
    output wire                  irq
);

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;
    localparam [1:0] IDX_CTRL    = 2'd0;
    localparam [1:0] IDX_LOAD    = 2'd1;
    localparam [1:0] IDX_COUNT   = 2'd2;
    localparam [1:0] IDX_STATUS  = 2'd3;
    localparam [ADDR_WIDTH-1:0] ADDR_ZERO = {ADDR_WIDTH{1'b0}};

    // ------------------------------------------------------------------
    // Channel state
    // ------------------------------------------------------------------
    reg                  aw_held;
    reg [ADDR_WIDTH-1:0] aw_addr_q;
    reg                  w_held;
    reg [31:0]           w_data_q;
    reg [3:0]            w_strb_q;
    reg                  bvalid_q;
    reg [1:0]            bresp_q;
    reg                  rvalid_q;
    reg [31:0]           rdata_q;
    reg [1:0]            rresp_q;

    // ------------------------------------------------------------------
    // Timer state
    // ------------------------------------------------------------------
    reg        en_q;
    reg        ie_q;
    reg        mode_q;
    reg        expired_q;
    reg [31:0] load_q;
    reg [31:0] count_q;

    // READY signals depend on flops only (no input-to-output path).
    wire awready_w = ~aw_held & ~bvalid_q;
    wire wready_w  = ~w_held  & ~bvalid_q;
    wire arready_w = ~rvalid_q;

    wire aw_hs = s_axil_awvalid & awready_w;
    wire w_hs  = s_axil_wvalid  & wready_w;
    wire ar_hs = s_axil_arvalid & arready_w;

    // Both halves present (held or arriving): the write takes effect.
    wire do_write = (aw_held | aw_hs) & (w_held | w_hs) & ~bvalid_q;

    wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
    wire [31:0]           wr_data = w_held  ? w_data_q  : s_axil_wdata;
    wire [3:0]            wr_strb = w_held  ? w_strb_q  : s_axil_wstrb;

    // Address decode: word aligned and below 0x10.
    wire       wr_mapped = (wr_addr[1:0] == 2'b00) && ((wr_addr >> 4) == ADDR_ZERO);
    wire [1:0] wr_idx    = wr_addr[3:2];
    wire       wr_ok     = wr_mapped && (wr_idx != IDX_COUNT);
    wire       wr_ctrl   = do_write && wr_mapped && (wr_idx == IDX_CTRL) && wr_strb[0];
    wire       wr_load   = do_write && wr_mapped && (wr_idx == IDX_LOAD);
    wire       wr_clear  = do_write && wr_mapped && (wr_idx == IDX_STATUS) &&
                           wr_strb[0] && wr_data[0];

    wire       rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                           ((s_axil_araddr >> 4) == ADDR_ZERO);
    wire [1:0] rd_idx    = s_axil_araddr[3:2];

    // Last cycle of a count: a COUNT of 1 or 0 while enabled.
    wire count_end = en_q && (count_q <= 32'd1);

    // ------------------------------------------------------------------
    // Read data mux (register values before the accepting edge)
    // ------------------------------------------------------------------
    reg [31:0] rd_data;
    reg [1:0]  rd_resp;

    always @* begin
        rd_data = 32'd0;
        rd_resp = RESP_SLVERR;
        if (rd_mapped) begin
            rd_resp = RESP_OKAY;
            case (rd_idx)
                IDX_CTRL:   rd_data = {29'd0, mode_q, ie_q, en_q};
                IDX_LOAD:   rd_data = load_q;
                IDX_COUNT:  rd_data = count_q;
                IDX_STATUS: rd_data = {31'd0, expired_q};
                default:    rd_data = 32'd0;
            endcase
        end
    end

    // ------------------------------------------------------------------
    // Timer next state; priorities fall out of last-assignment-wins
    // ------------------------------------------------------------------
    reg        en_d;
    reg        ie_d;
    reg        mode_d;
    reg        expired_d;
    reg [31:0] load_d;
    reg [31:0] count_d;

    always @* begin
        en_d      = en_q;
        ie_d      = ie_q;
        mode_d    = mode_q;
        expired_d = expired_q;
        load_d    = load_q;
        count_d   = count_q;

        // 1. The count step.
        if (en_q) begin
            if (count_end) begin
                if (mode_q) begin
                    count_d = load_q;
                end else begin
                    count_d = 32'd0;
                    en_d    = 1'b0;
                end
            end else begin
                count_d = count_q - 32'd1;
            end
        end

        // 2. EXPIRED: clear, then set (a count end beats a clear).
        if (wr_clear) begin
            expired_d = 1'b0;
        end
        if (count_end) begin
            expired_d = 1'b1;
        end

        // 3. CTRL write wins over the count step for EN and COUNT.
        if (wr_ctrl) begin
            ie_d   = wr_data[1];
            mode_d = wr_data[2];
            if (wr_data[0]) begin
                en_d    = 1'b1;
                count_d = load_q;
            end else begin
                en_d = 1'b0;
            end
        end

        // 4. LOAD write merges strobed bytes.
        if (wr_load) begin
            if (wr_strb[0]) load_d[7:0]   = wr_data[7:0];
            if (wr_strb[1]) load_d[15:8]  = wr_data[15:8];
            if (wr_strb[2]) load_d[23:16] = wr_data[23:16];
            if (wr_strb[3]) load_d[31:24] = wr_data[31:24];
        end
    end

    always @(posedge aclk) begin
        if (!aresetn) begin
            en_q      <= 1'b0;
            ie_q      <= 1'b0;
            mode_q    <= 1'b0;
            expired_q <= 1'b0;
            load_q    <= 32'd0;
            count_q   <= 32'd0;
        end else begin
            en_q      <= en_d;
            ie_q      <= ie_d;
            mode_q    <= mode_d;
            expired_q <= expired_d;
            load_q    <= load_d;
            count_q   <= count_d;
        end
    end

    // ------------------------------------------------------------------
    // Write channels
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held   <= 1'b0;
            aw_addr_q <= ADDR_ZERO;
            w_held    <= 1'b0;
            w_data_q  <= 32'd0;
            w_strb_q  <= 4'd0;
            bvalid_q  <= 1'b0;
            bresp_q   <= RESP_OKAY;
        end else begin
            if (do_write) begin
                aw_held  <= 1'b0;
                w_held   <= 1'b0;
                bvalid_q <= 1'b1;
                bresp_q  <= wr_ok ? RESP_OKAY : RESP_SLVERR;
            end else begin
                if (aw_hs) begin
                    aw_held   <= 1'b1;
                    aw_addr_q <= s_axil_awaddr;
                end
                if (w_hs) begin
                    w_held   <= 1'b1;
                    w_data_q <= s_axil_wdata;
                    w_strb_q <= s_axil_wstrb;
                end
                if (bvalid_q && s_axil_bready) begin
                    bvalid_q <= 1'b0;
                end
            end
        end
    end

    // ------------------------------------------------------------------
    // Read channels
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            rvalid_q <= 1'b0;
            rdata_q  <= 32'd0;
            rresp_q  <= RESP_OKAY;
        end else begin
            if (ar_hs) begin
                rvalid_q <= 1'b1;
                rdata_q  <= rd_data;
                rresp_q  <= rd_resp;
            end else if (rvalid_q && s_axil_rready) begin
                rvalid_q <= 1'b0;
            end
        end
    end

    assign s_axil_awready = awready_w;
    assign s_axil_wready  = wready_w;
    assign s_axil_bvalid  = bvalid_q;
    assign s_axil_bresp   = bresp_q;
    assign s_axil_arready = arready_w;
    assign s_axil_rvalid  = rvalid_q;
    assign s_axil_rdata   = rdata_q;
    assign s_axil_rresp   = rresp_q;
    assign irq            = expired_q & ie_q;

`ifdef FORMAL
    // Design-intent assertions (not yet run by any tool).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge aclk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume(!aresetn);
    end

    always @(posedge aclk) begin
        if (f_past_valid && $past(!aresetn)) begin
            assert(!bvalid_q);
            assert(!rvalid_q);
            assert(!en_q);
            assert(!expired_q);
            assert(!aw_held);
            assert(!w_held);
        end
    end

    always @(*) begin
        if (bvalid_q) assert(!aw_held && !w_held);
        assert(bresp_q == RESP_OKAY || bresp_q == RESP_SLVERR);
        assert(rresp_q == RESP_OKAY || rresp_q == RESP_SLVERR);
        assert(irq == (expired_q && ie_q));
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: axil_timer_tb.v ===
// axil_timer_tb: self-checking directed testbench for axil_timer.
// Two lanes share one bus: dut8 (ADDR_WIDTH 8) and dut4 (ADDR_WIDTH 4).
// Inputs change 1 time unit after a rising edge; outputs are sampled there
// or at the falling edge.
module axil_timer_tb;

    localparam [1:0] OKAY   = 2'b00;
    localparam [1:0] SLVERR = 2'b10;

    reg aclk = 1'b0;
    always #5 aclk = ~aclk;

    reg        aresetn = 1'b0;
    reg [7:0]  awaddr  = 8'h00;
    reg        awvalid = 1'b0;
    reg [31:0] wdata   = 32'h0000_0000;
    reg [3:0]  wstrb   = 4'h0;
    reg        wvalid  = 1'b0;
    reg        bready  = 1'b0;
    reg [7:0]  araddr  = 8'h00;
    reg        arvalid = 1'b0;
    reg        rready  = 1'b0;

    wire        awready8, wready8, bvalid8, arready8, rvalid8, irq8;
    wire [1:0]  bresp8, rresp8;
    wire [31:0] rdata8;
    wire        awready4, wready4, bvalid4, arready4, rvalid4, irq4;
    wire [1:0]  bresp4, rresp4;
    wire [31:0] rdata4;

    axil_timer #(.ADDR_WIDTH(8)) dut8 (
        .aclk(aclk), .aresetn(aresetn),
        .s_axil_awaddr(awaddr), .s_axil_awvalid(awvalid), .s_axil_awready(awready8),
        .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid), .s_axil_wready(wready8),
        .s_axil_bresp(bresp8), .s_axil_bvalid(bvalid8), .s_axil_bready(bready),
        .s_axil_araddr(araddr), .s_axil_arvalid(arvalid), .s_axil_arready(arready8),
        .s_axil_rdata(rdata8), .s_axil_rresp(rresp8), .s_axil_rvalid(rvalid8), .s_axil_rready(rready),
        .irq(irq8)
    );

    axil_timer #(.ADDR_WIDTH(4)) dut4 (
        .aclk(aclk), .aresetn(aresetn),
        .s_axil_awaddr(awaddr[3:0]), .s_axil_awvalid(awvalid), .s_axil_awready(awready4),
        .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid), .s_axil_wready(wready4),
        .s_axil_bresp(bresp4), .s_axil_bvalid(bvalid4), .s_axil_bready(bready),
        .s_axil_araddr(araddr[3:0]), .s_axil_arvalid(arvalid), .s_axil_arready(arready4),
        .s_axil_rdata(rdata4), .s_axil_rresp(rresp4), .s_axil_rvalid(rvalid4), .s_axil_rready(rready),
        .irq(irq4)
    );

    // ------------------------------------------------------------------
    // Bookkeeping
    // ------------------------------------------------------------------
    integer cycle = 0;                 // index of the last rising edge
    always @(posedge aclk) cycle <= cycle + 1;

    integer passed = 0;
    integer failed = 0;
    integer phase  = 0;
    integer rc     = 0;
    reg     done   = 1'b0;
    reg [8*64-1:0] nonce = {(8*64){1'b0}};

    // Monitors (written only here)
    reg     mon_en        = 1'b0;
    reg     lockstep_irq  = 1'b1;
    reg     irq_last      = 1'b0;
    integer irq_rise_edge = -1;
    integer irq_rises     = 0;
    integer lock_errs     = 0;

    always @(negedge aclk) begin
        if (mon_en) begin
            if (irq8 === 1'b1 && irq_last !== 1'b1) begin
                irq_rise_edge = cycle;
                irq_rises = irq_rises + 1;
            end
            if ((awready8 !== awready4) || (wready8 !== wready4) ||
                (bvalid8 !== bvalid4) || (arready8 !== arready4) ||
                (rvalid8 !== rvalid4) || (lockstep_irq && (irq8 !== irq4))) begin
                lock_errs = lock_errs + 1;
                $error("cycle %0d: ADDR_WIDTH 8 and 4 lanes disagree on handshake or irq", cycle);
            end
        end
        irq_last = irq8;
    end

    // Results of the last transfer
    reg [1:0]  b8, b4, rr8, rr4;
    reg [31:0] r8, r4;
    integer    wr_edge = 0;
    integer    ar_edge = 0;

    // ------------------------------------------------------------------
    // Check helpers
    // ------------------------------------------------------------------
    task chk1(input integer id, input got, input exp);
        begin
            if (got === exp) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("phase %0d check %0d: got %b, expected %b", phase, id, got, exp);
            end
        end
    endtask

    task chk2(input integer id, input [1:0] got, input [1:0] exp);
        begin
            if (got === exp) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("phase %0d check %0d: got %b, expected %b", phase, id, got, exp);
            end
        end
    endtask

    task chk32(input integer id, input [31:0] got, input [31:0] exp);
        begin
            if (got === exp) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("phase %0d check %0d: got %h, expected %h", phase, id, got, exp);
            end
        end
    endtask

    task chkint(input integer id, input integer got, input integer exp);
        begin
            if (got == exp) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("phase %0d check %0d: got %0d, expected %0d", phase, id, got, exp);
            end
        end
    endtask

    task tick;
        begin
            @(posedge aclk);
            #1;
        end
    endtask

    task wait_edge(input integer e);
        begin
            while (cycle < e) tick;
        end
    endtask

    // ------------------------------------------------------------------
    // Bus tasks. order: 0 AW and W together, 1 AW first, 2 W first.
    // ------------------------------------------------------------------
    task axi_write(input [7:0] addr, input [31:0] data, input [3:0] strb,
                   input integer order, input integer bdelay);
        reg aw_left;
        reg w_left;
        reg aw_go;
        reg w_go;
        integer k;
        begin
            awaddr  = addr;
            wdata   = data;
            wstrb   = strb;
            aw_left = 1'b1;
            w_left  = 1'b1;
            awvalid = (order != 2) ? 1'b1 : 1'b0;
            wvalid  = (order != 1) ? 1'b1 : 1'b0;
            while (aw_left || w_left) begin
                @(negedge aclk);
                aw_go = awvalid & awready8;
                w_go  = wvalid & wready8;
                @(posedge aclk);
                #1;
                if (aw_go) begin aw_left = 1'b0; awvalid = 1'b0; end
                if (w_go)  begin w_left  = 1'b0; wvalid  = 1'b0; end
                if (order == 1 && !aw_left && w_left) wvalid  = 1'b1;
                if (order == 2 && !w_left && aw_left) awvalid = 1'b1;
            end
            wr_edge = cycle;
            chk1(1, bvalid8, 1'b1);
            chk1(2, bvalid4, 1'b1);
            chk1(3, awready8, 1'b0);
            chk1(4, wready8, 1'b0);
            b8 = bresp8;
            b4 = bresp4;
            for (k = 0; k < bdelay; k = k + 1) begin
                tick;
                chk1(5, bvalid8, 1'b1);
                chk2(6, bresp8, b8);
                chk1(7, bvalid4, 1'b1);
                chk2(8, bresp4, b4);
                chk1(9, awready8, 1'b0);
            end
            bready = 1'b1;
            tick;
            bready = 1'b0;
            chk1(10, bvalid8, 1'b0);
            chk1(11, bvalid4, 1'b0);
        end
    endtask

    task axi_read(input [7:0] addr, input integer rdelay);
        reg ar_go;
        integer k;
        begin
            araddr  = addr;
            arvalid = 1'b1;
            ar_go   = 1'b0;
            while (!ar_go) begin
                @(negedge aclk);
                ar_go = arready8;
                @(posedge aclk);
                #1;
            end
            arvalid = 1'b0;
            ar_edge = cycle;
            chk1(20, rvalid8, 1'b1);
            chk1(21, rvalid4, 1'b1);
            chk1(22, arready8, 1'b0);
            r8  = rdata8;
            rr8 = rresp8;
            r4  = rdata4;
            rr4 = rresp4;
            for (k = 0; k < rdelay; k = k + 1) begin
                tick;
                chk1(23, rvalid8, 1'b1);
                chk32(24, rdata8, r8);
                chk2(25, rresp8, rr8);
                chk32(26, rdata4, r4);
                chk2(27, rresp4, rr4);
                chk1(28, arready8, 1'b0);
            end
            rready = 1'b1;
            tick;
            rready = 1'b0;
            chk1(29, rvalid8, 1'b0);
            chk1(30, rvalid4, 1'b0);
        end
    endtask

    task write_chk(input integer id, input [7:0] addr, input [31:0] data, input [3:0] strb,
                   input integer order, input integer bdelay, input [1:0] resp);
        begin
            axi_write(addr, data, strb, order, bdelay);
            chk2(id, b8, resp);
            chk2(id, b4, resp);
        end
    endtask

    task write_chk2(input integer id, input [7:0] addr, input [31:0] data, input [3:0] strb,
                    input [1:0] resp8, input [1:0] resp4);
        begin
            axi_write(addr, data, strb, 0, 0);
            chk2(id, b8, resp8);
            chk2(id, b4, resp4);
        end
    endtask

    task read_chk(input integer id, input [7:0] addr, input [31:0] exp, input [1:0] resp,
                  input integer rdelay);
        begin
            axi_read(addr, rdelay);
            chk32(id, r8, exp);
            chk2(id, rr8, resp);
            chk32(id, r4, exp);
            chk2(id, rr4, resp);
        end
    endtask

    task read_chk2(input integer id, input [7:0] addr, input [31:0] exp8, input [1:0] resp8,
                   input [31:0] exp4, input [1:0] resp4);
        begin
            axi_read(addr, 0);
            chk32(id, r8, exp8);
            chk2(id, rr8, resp8);
            chk32(id, r4, exp4);
            chk2(id, rr4, resp4);
        end
    endtask

    // ------------------------------------------------------------------
    // Watchdog
    // ------------------------------------------------------------------
    initial begin : watchdog
        #200000;
        if (!done) begin
            $error("timeout: the test did not finish");
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
            $finish;
        end
    end

    // ------------------------------------------------------------------
    // Directed sequence
    // ------------------------------------------------------------------
    integer e0, r0, s0, rb, frozen;

    initial begin : main
        rc = $value$plusargs("nirmaan_nonce=%s", nonce);

        // Reset
        aresetn = 1'b0;
        repeat (3) tick;
        aresetn = 1'b1;
        tick;
        mon_en = 1'b1;

        // ---------------- Phase 1: reset values ----------------
        phase = 1;
        chk1(1, awready8, 1'b1);
        chk1(2, wready8, 1'b1);
        chk1(3, arready8, 1'b1);
        chk1(4, bvalid8, 1'b0);
        chk1(5, rvalid8, 1'b0);
        chk1(6, irq8, 1'b0);
        chk1(7, irq4, 1'b0);
        read_chk(10, 8'h00, 32'h0000_0000, OKAY, 0);
        read_chk(11, 8'h04, 32'h0000_0000, OKAY, 0);
        read_chk(12, 8'h08, 32'h0000_0000, OKAY, 0);
        read_chk(13, 8'h0C, 32'h0000_0000, OKAY, 0);

        // ---------------- Phase 2: strobes, orders, backpressure ----------------
        phase = 2;
        write_chk(1, 8'h04, 32'hFFFF_FFFF, 4'hF, 0, 0, OKAY);
        read_chk(2, 8'h04, 32'hFFFF_FFFF, OKAY, 0);
        write_chk(3, 8'h04, 32'h1234_5678, 4'h5, 1, 3, OKAY);
        read_chk(4, 8'h04, 32'hFF34_FF78, OKAY, 4);
        write_chk(5, 8'h04, 32'hA5A5_A5A5, 4'hA, 2, 2, OKAY);
        read_chk(6, 8'h04, 32'hA534_A578, OKAY, 0);
        write_chk(7, 8'h04, 32'h0000_0000, 4'h0, 0, 1, OKAY);
        read_chk(8, 8'h04, 32'hA534_A578, OKAY, 0);
        // A write and a read accepted on the same edge: the read sees the
        // value before that edge.
        awaddr  = 8'h04;
        wdata   = 32'h1111_1111;
        wstrb   = 4'hF;
        awvalid = 1'b1;
        wvalid  = 1'b1;
        araddr  = 8'h04;
        arvalid = 1'b1;
        @(negedge aclk);
        chk1(9, awready8, 1'b1);
        chk1(10, wready8, 1'b1);
        chk1(11, arready8, 1'b1);
        @(posedge aclk);
        #1;
        awvalid = 1'b0;
        wvalid  = 1'b0;
        arvalid = 1'b0;
        chk1(12, bvalid8, 1'b1);
        chk1(13, rvalid8, 1'b1);
        chk2(14, bresp8, OKAY);
        chk2(15, bresp4, OKAY);
        chk32(16, rdata8, 32'hA534_A578);
        chk32(17, rdata4, 32'hA534_A578);
        bready = 1'b1;
        rready = 1'b1;
        tick;
        bready = 1'b0;
        rready = 1'b0;
        chk1(18, bvalid8, 1'b0);
        chk1(19, rvalid8, 1'b0);
        read_chk(20, 8'h04, 32'h1111_1111, OKAY, 0);

        // ---------------- Phase 3: SLVERR policy, CTRL without wstrb[0] ----------------
        phase = 3;
        write_chk(1, 8'h08, 32'h0000_0055, 4'hF, 0, 0, SLVERR);
        read_chk(2, 8'h08, 32'h0000_0000, OKAY, 0);
        write_chk(3, 8'h06, 32'h0000_0000, 4'hF, 0, 0, SLVERR);
        read_chk(4, 8'h04, 32'h1111_1111, OKAY, 0);
        read_chk(5, 8'h06, 32'h0000_0000, SLVERR, 0);
        read_chk(6, 8'h01, 32'h0000_0000, SLVERR, 0);
        write_chk(7, 8'h01, 32'h0000_0007, 4'hF, 1, 0, SLVERR);
        read_chk(8, 8'h00, 32'h0000_0000, OKAY, 0);
        write_chk(9, 8'h00, 32'h0000_0007, 4'hE, 0, 0, OKAY);
        read_chk(10, 8'h00, 32'h0000_0000, OKAY, 0);
        repeat (5) tick;
        read_chk(11, 8'h08, 32'h0000_0000, OKAY, 0);
        chkint(12, irq_rises, 0);
        write_chk(13, 8'h0C, 32'h0000_0001, 4'hF, 0, 0, OKAY);
        read_chk(14, 8'h0C, 32'h0000_0000, OKAY, 0);

        // ---------------- Phase 4: one-shot timing ----------------
        phase = 4;
        write_chk(1, 8'h04, 32'd5, 4'hF, 0, 0, OKAY);
        rb = irq_rises;
        write_chk(2, 8'h00, 32'h0000_0003, 4'h1, 0, 0, OKAY);
        e0 = wr_edge;
        wait_edge(e0 + 6);
        chkint(3, irq_rise_edge, e0 + 5);
        chkint(4, irq_rises, rb + 1);
        chk1(5, irq8, 1'b1);
        read_chk(6, 8'h00, 32'h0000_0002, OKAY, 0);
        read_chk(7, 8'h08, 32'h0000_0000, OKAY, 0);
        read_chk(8, 8'h0C, 32'h0000_0001, OKAY, 0);
        repeat (12) tick;
        chkint(9, irq_rises, rb + 1);
        chk1(10, irq8, 1'b1);
        write_chk(11, 8'h0C, 32'h0000_0000, 4'hF, 0, 0, OKAY);
        read_chk(12, 8'h0C, 32'h0000_0001, OKAY, 0);
        write_chk(13, 8'h0C, 32'h0000_0001, 4'hE, 0, 0, OKAY);
        read_chk(14, 8'h0C, 32'h0000_0001, OKAY, 0);
        chk1(15, irq8, 1'b1);
        write_chk(16, 8'h0C, 32'h0000_0001, 4'h1, 0, 0, OKAY);
        chk1(17, irq8, 1'b0);
        read_chk(18, 8'h0C, 32'h0000_0000, OKAY, 0);
        // LOAD of 1
        write_chk(19, 8'h04, 32'd1, 4'hF, 0, 0, OKAY);
        rb = irq_rises;
        write_chk(20, 8'h00, 32'h0000_0003, 4'h1, 0, 0, OKAY);
        e0 = wr_edge;
        wait_edge(e0 + 2);
        chkint(21, irq_rise_edge, e0 + 1);
        chkint(22, irq_rises, rb + 1);
        read_chk(23, 8'h00, 32'h0000_0002, OKAY, 0);
        write_chk(24, 8'h0C, 32'h0000_0001, 4'h1, 0, 0, OKAY);
        chk1(25, irq8, 1'b0);
        // LOAD of 0 counts as 1
        write_chk(26, 8'h04, 32'd0, 4'hF, 0, 0, OKAY);
        rb = irq_rises;
        write_chk(27, 8'h00, 32'h0000_0003, 4'h1, 0, 0, OKAY);
        e0 = wr_edge;
        wait_edge(e0 + 2);
        chkint(28, irq_rise_edge, e0 + 1);
        chkint(29, irq_rises, rb + 1);
        read_chk(30, 8'h00, 32'h0000_0002, OKAY, 0);
        read_chk(31, 8'h08, 32'h0000_0000, OKAY, 0);
        repeat (6) tick;
        chkint(32, irq_rises, rb + 1);
        write_chk(33, 8'h0C, 32'h0000_0001, 4'h1, 0, 0, OKAY);
        chk1(34, irq8, 1'b0);

        // ---------------- Phase 5: interrupt enable on a pending expiry ----------------
        phase = 5;
        write_chk(1, 8'h04, 32'd3, 4'hF, 0, 0, OKAY);
        rb = irq_rises;
        write_chk(2, 8'h00, 32'h0000_0001, 4'h1, 0, 0, OKAY);
        e0 = wr_edge;
        wait_edge(e0 + 6);
        chk1(3, irq8, 1'b0);
        chkint(4, irq_rises, rb);
        read_chk(5, 8'h0C, 32'h0000_0001, OKAY, 0);
        read_chk(6, 8'h00, 32'h0000_0000, OKAY, 0);
        write_chk(7, 8'h00, 32'h0000_0002, 4'h1, 0, 0, OKAY);
        chk1(8, irq8, 1'b1);
        chkint(9, irq_rise_edge, wr_edge);
        chkint(10, irq_rises, rb + 1);
        write_chk(11, 8'h00, 32'h0000_0000, 4'h1, 0, 0, OKAY);
        chk1(12, irq8, 1'b0);
        read_chk(13, 8'h0C, 32'h0000_0001, OKAY, 0);
        write_chk(14, 8'h00, 32'h0000_0002, 4'h1, 0, 0, OKAY);
        chk1(15, irq8, 1'b1);
        write_chk(16, 8'h0C, 32'h0000_0001, 4'h1, 0, 0, OKAY);
        chk1(17, irq8, 1'b0);

        // ---------------- Phase 6: periodic timing, clear on the end edge, stop ----------------
        phase = 6;
        write_chk(1, 8'h04, 32'd20, 4'hF, 0, 0, OKAY);
        rb = irq_rises;
        write_chk(2, 8'h00, 32'h0000_0007, 4'h1, 0, 0, OKAY);
        e0 = wr_edge;
        wait_edge(e0 + 21);
        chkint(3, irq_rise_edge, e0 + 20);
        chkint(4, irq_rises, rb + 1);
        axi_read(8'h08, 0);
        chk32(5, r8, 20 - ((ar_edge - 1 - e0) % 20));
        chk32(6, r4, 20 - ((ar_edge - 1 - e0) % 20));
        read_chk(7, 8'h00, 32'h0000_0007, OKAY, 0);
        // Acknowledge the pending expiry on the very edge the next count ends.
        wait_edge(e0 + 39);
        write_chk(8, 8'h0C, 32'h0000_0001, 4'h1, 0, 0, OKAY);
        chkint(9, wr_edge, e0 + 40);
        chk1(10, irq8, 1'b1);
        chkint(11, irq_rises, rb + 1);
        read_chk(12, 8'h0C, 32'h0000_0001, OKAY, 0);
        write_chk(13, 8'h0C, 32'h0000_0001, 4'h1, 0, 0, OKAY);
        chk1(14, irq8, 1'b0);
        wait_edge(e0 + 61);
        chkint(15, irq_rise_edge, e0 + 60);
        chkint(16, irq_rises, rb + 2);
        write_chk(17, 8'h0C, 32'h0000_0001, 4'h1, 0, 0, OKAY);
        chk1(18, irq8, 1'b0);
        axi_read(8'h08, 2);
        chk32(19, r8, 20 - ((ar_edge - 1 - e0) % 20));
        chk32(20, r4, 20 - ((ar_edge - 1 - e0) % 20));
        wait_edge(e0 + 81);
        chkint(21, irq_rise_edge, e0 + 80);
        chkint(22, irq_rises, rb + 3);
        write_chk(23, 8'h0C, 32'h0000_0001, 4'h1, 0, 0, OKAY);
        chk1(24, irq8, 1'b0);
        // Stop: COUNT freezes at the value the stopping edge gives it.
        write_chk(25, 8'h00, 32'h0000_0006, 4'h1, 0, 0, OKAY);
        s0 = wr_edge;
        frozen = 20 - ((s0 - e0) % 20);
        repeat (45) tick;
        chkint(26, irq_rises, rb + 3);
        chk1(27, irq8, 1'b0);
        read_chk(28, 8'h08, frozen, OKAY, 0);
        read_chk(29, 8'h00, 32'h0000_0006, OKAY, 0);
        read_chk(30, 8'h0C, 32'h0000_0000, OKAY, 0);

        // ---------------- Phase 7: restarts and CTRL writes on the end edge ----------------
        phase = 7;
        // 7a: restart while counting
        write_chk(1, 8'h04, 32'd10, 4'hF, 0, 0, OKAY);
        rb = irq_rises;
        write_chk(2, 8'h00, 32'h0000_0003, 4'h1, 0, 0, OKAY);
        e0 = wr_edge;
        wait_edge(e0 + 3);
        write_chk(3, 8'h00, 32'h0000_0003, 4'h1, 0, 0, OKAY);
        r0 = wr_edge;
        chkint(4, r0, e0 + 4);
        axi_read(8'h08, 0);
        chk32(5, r8, 10 - (ar_edge - 1 - r0));
        wait_edge(r0 + 11);
        chkint(6, irq_rise_edge, r0 + 10);
        chkint(7, irq_rises, rb + 1);
        read_chk(8, 8'h00, 32'h0000_0002, OKAY, 0);
        write_chk(9, 8'h0C, 32'h0000_0001, 4'h1, 0, 0, OKAY);
        chk1(10, irq8, 1'b0);
        // 7b: one-shot, EN 1 written on the end edge restarts from LOAD
        write_chk(11, 8'h04, 32'd12, 4'hF, 0, 0, OKAY);
        rb = irq_rises;
        write_chk(12, 8'h00, 32'h0000_0003, 4'h1, 0, 0, OKAY);
        e0 = wr_edge;
        wait_edge(e0 + 11);
        write_chk(13, 8'h00, 32'h0000_0003, 4'h1, 0, 0, OKAY);
        r0 = wr_edge;
        chkint(14, r0, e0 + 12);
        chkint(15, irq_rise_edge, e0 + 12);
        chkint(16, irq_rises, rb + 1);
        read_chk(17, 8'h00, 32'h0000_0003, OKAY, 0);
        axi_read(8'h08, 0);
        chk32(18, r8, 12 - (ar_edge - 1 - r0));
        write_chk(19, 8'h0C, 32'h0000_0001, 4'h1, 0, 0, OKAY);
        chk1(20, irq8, 1'b0);
        wait_edge(r0 + 13);
        chkint(21, irq_rise_edge, r0 + 12);
        chkint(22, irq_rises, rb + 2);
        read_chk(23, 8'h00, 32'h0000_0002, OKAY, 0);
        read_chk(24, 8'h08, 32'h0000_0000, OKAY, 0);
        write_chk(25, 8'h0C, 32'h0000_0001, 4'h1, 0, 0, OKAY);
        chk1(26, irq8, 1'b0);
        // 7c: periodic, EN 0 written on the end edge: COUNT takes LOAD, stops
        write_chk(27, 8'h04, 32'd8, 4'hF, 0, 0, OKAY);
        rb = irq_rises;
        write_chk(28, 8'h00, 32'h0000_0007, 4'h1, 0, 0, OKAY);
        e0 = wr_edge;
        wait_edge(e0 + 7);
        write_chk(29, 8'h00, 32'h0000_0006, 4'h1, 0, 0, OKAY);
        chkint(30, wr_edge, e0 + 8);
        chkint(31, irq_rise_edge, e0 + 8);
        read_chk(32, 8'h00, 32'h0000_0006, OKAY, 0);
        read_chk(33, 8'h08, 32'd8, OKAY, 0);
        read_chk(34, 8'h0C, 32'h0000_0001, OKAY, 0);
        repeat (20) tick;
        chkint(35, irq_rises, rb + 1);
        write_chk(36, 8'h0C, 32'h0000_0001, 4'h1, 0, 0, OKAY);
        chk1(37, irq8, 1'b0);

        // ---------------- Phase 8: reset during a count with responses pending ----------------
        phase = 8;
        write_chk(1, 8'h04, 32'd50, 4'hF, 0, 0, OKAY);
        rb = irq_rises;
        write_chk(2, 8'h00, 32'h0000_0003, 4'h1, 0, 0, OKAY);
        repeat (3) tick;
        awaddr  = 8'h04;
        wdata   = 32'h0000_1234;
        wstrb   = 4'hF;
        awvalid = 1'b1;
        wvalid  = 1'b1;
        araddr  = 8'h00;
        arvalid = 1'b1;
        tick;
        awvalid = 1'b0;
        wvalid  = 1'b0;
        arvalid = 1'b0;
        chk1(3, bvalid8, 1'b1);
        chk1(4, rvalid8, 1'b1);
        chk32(5, rdata8, 32'h0000_0003);
        tick;
        chk1(6, bvalid8, 1'b1);
        chk1(7, rvalid8, 1'b1);
        aresetn = 1'b0;
        tick;
        chk1(8, bvalid8, 1'b0);
        chk1(9, rvalid8, 1'b0);
        chk1(10, bvalid4, 1'b0);
        chk1(11, rvalid4, 1'b0);
        chk1(12, irq8, 1'b0);
        chk1(13, awready8, 1'b1);
        chk1(14, arready8, 1'b1);
        tick;
        aresetn = 1'b1;
        tick;
        read_chk(15, 8'h00, 32'h0000_0000, OKAY, 0);
        read_chk(16, 8'h04, 32'h0000_0000, OKAY, 0);
        read_chk(17, 8'h08, 32'h0000_0000, OKAY, 0);
        read_chk(18, 8'h0C, 32'h0000_0000, OKAY, 0);
        repeat (60) tick;
        chkint(19, irq_rises, rb);
        chk1(20, irq8, 1'b0);

        // ---------------- Phase 9: offsets from 0x10 up at ADDR_WIDTH 8 ----------------
        // dut4 sees only addr[3:0], so these accesses alias its registers;
        // dut8 must answer SLVERR and change nothing.
        phase = 9;
        lockstep_irq = 1'b0;
        write_chk(1, 8'h04, 32'h0000_0042, 4'hF, 0, 0, OKAY);
        write_chk2(2, 8'h14, 32'hDEAD_BEEF, 4'hF, SLVERR, OKAY);
        read_chk2(3, 8'h04, 32'h0000_0042, OKAY, 32'hDEAD_BEEF, OKAY);
        read_chk2(4, 8'h14, 32'h0000_0000, SLVERR, 32'hDEAD_BEEF, OKAY);
        write_chk2(5, 8'h18, 32'h0000_0005, 4'hF, SLVERR, SLVERR);
        write_chk2(6, 8'h1C, 32'h0000_0001, 4'hF, SLVERR, OKAY);
        write_chk2(7, 8'h80, 32'h0000_0002, 4'hF, SLVERR, OKAY);
        read_chk2(8, 8'h00, 32'h0000_0000, OKAY, 32'h0000_0002, OKAY);
        read_chk2(9, 8'h10, 32'h0000_0000, SLVERR, 32'h0000_0002, OKAY);
        read_chk2(10, 8'hF0, 32'h0000_0000, SLVERR, 32'h0000_0002, OKAY);
        read_chk2(11, 8'hFC, 32'h0000_0000, SLVERR, 32'h0000_0000, OKAY);
        read_chk2(12, 8'h18, 32'h0000_0000, SLVERR, 32'h0000_0000, OKAY);
        read_chk2(13, 8'h08, 32'h0000_0000, OKAY, 32'h0000_0000, OKAY);
        read_chk2(14, 8'h0C, 32'h0000_0000, OKAY, 32'h0000_0000, OKAY);
        read_chk2(15, 8'h43, 32'h0000_0000, SLVERR, 32'h0000_0000, SLVERR);
        chk1(16, irq8, 1'b0);
        chk1(17, irq4, 1'b0);

        // ---------------- Verdict ----------------
        phase = 10;
        chkint(1, lock_errs, 0);
        done = 1'b1;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
